"use client";
import { FormEvent, useState } from "react";
type State="idle"|"loading"|"success"|"error";
export default function ContactForm(){const [state,setState]=useState<State>("idle");const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;if(!form.checkValidity()){form.reportValidity();setState("error");return}setState("loading");window.setTimeout(()=>setState("success"),650)};return <div className="contact-form-card" data-reveal><h2>Claim Your Pass</h2><p>Tell us a little about you and pick a pass. We’ll confirm your seat and send an invoice within one working day.</p><form onSubmit={submit} noValidate><label>NAME<input name="name" required placeholder="Your full name"/></label><label>WORK EMAIL<input type="email" name="email" required placeholder="yourcompany@email.com"/></label><label>PHONE NUMBER<input type="tel" name="phone" required pattern="[+0-9 ()-]{8,}" placeholder="+91 9121675082"/></label><label>TOPIC<select name="topic" defaultValue="Tickets"><option>Tickets</option><option>Tier-1</option><option>Tier-2</option></select></label><p className="form-disclaimer">BY SUBMITTING, YOU AGREE THAT SUCCESSWIKIS MAY USE YOUR DETAILS TO RESPOND TO THIS ENQUIRY.</p><button type="submit" disabled={state==="loading"}><span>↦</span>{state==="loading"?"SENDING…":"SEND INQUIRY"}</button>{state==="error"&&<output className="form-message error">Please complete all required fields.</output>}{state==="success"&&<output className="form-message success">Thanks — your enquiry is ready for the SuccessWikis team.</output>}<small><i/>Typical response: 1–2 business days.</small></form></div>}
